import{_ as s,a,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第二册：实践与进步 · 综合复习与自测 · 第28–36课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第二册：实践与进步 · 综合复习与自测 · 第28–36课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-2/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第19–27课","link":"/life/english/new-concept/book-2/review-part-03"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第37–45课","link":"/life/english/new-concept/book-2/review-part-05"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第19–27课","link":"/life/english/new-concept/book-2/review-part-03"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第37–45课","link":"/life/english/new-concept/book-2/review-part-05"}},"headers":[],"relativePath":"life/english/new-concept/book-2/review-part-04.md","filePath":"life/english/new-concept/book-2/review-part-04.md"}'),n={name:"life/english/new-concept/book-2/review-part-04.md"};function r(i,e,l,p,h,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-综合复习与自测-·-第28–36课" tabindex="-1">第二册：实践与进步 · 综合复习与自测 · 第28–36课 <a class="header-anchor" href="#第二册-实践与进步-·-综合复习与自测-·-第28–36课" aria-label="Permalink to &quot;第二册：实践与进步 · 综合复习与自测 · 第28–36课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-28-·-动名词与动词搭配" tabindex="-1">Lesson 28 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-28-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 28 · 动名词与动词搭配 {#lesson-28-·-动名词与动词搭配}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Parking beside this gate blocks the entrance.</p><h3 id="练习-1-27" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-27" aria-label="Permalink to &quot;练习 1 {#练习-1-27}&quot;">​</a></h3><p>填 block：Parking here ___ the entrance.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> blocks</p><p><strong>解析：</strong> 动名词短语主语按单数处理。</p></details><p><strong>表达迁移：</strong> 为一个入口写两句告示，再加一句解释通行需求。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Parking beside this gate blocks the entrance. Delivery vans need room to turn. Visitors can use the public car park nearby.</p><p>第一句的组织方式：Parking beside this gate 是动名词短语作主语，整体视为单数，谓语用 blocks。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Parking ... block 缺少第三人称单数词尾；一个动名词短语通常按单数看待。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-028">回看本课</a></p><h2 id="lesson-29-·-现在完成时与过去时间" tabindex="-1">Lesson 29 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-29-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 29 · 现在完成时与过去时间 {#lesson-29-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The small plane has carried a hundred passengers this week.</p><h3 id="练习-1-28" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-28" aria-label="Permalink to &quot;练习 1 {#练习-1-28}&quot;">​</a></h3><p>填 carry 的过去分词：The plane has ___ many passengers.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> carried</p><p><strong>解析：</strong> 辅音字母加 y 结尾变 y 为 i 再加 -ed。</p></details><p><strong>表达迁移：</strong> 介绍一个特别的交通服务，写累计成果、今天情况与下一步安排。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The small plane has carried a hundred passengers this week. Today the wind is too strong. The pilot has cancelled the afternoon flights.</p><p>第一句的组织方式：has carried 是现在完成时，a hundred passengers 为累计宾语，this week 连接过去活动与现在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：has flew 错误，fly 的过去分词是 flown；本例 carry 的过去分词是 carried。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-029">回看本课</a></p><h2 id="lesson-30-·-冠词与可数性" tabindex="-1">Lesson 30 · 冠词与可数性 <a class="header-anchor" href="#lesson-30-·-冠词与可数性" aria-label="Permalink to &quot;Lesson 30 · 冠词与可数性 {#lesson-30-·-冠词与可数性}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A ball landed in the river beside our picnic spot.</p><h3 id="练习-1-29" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-29" aria-label="Permalink to &quot;练习 1 {#练习-1-29}&quot;">​</a></h3><p>填 a/the：A ball landed nearby. ___ ball was blue.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The</p><p><strong>解析：</strong> 第二次提及同一对象用定冠词。</p></details><p><strong>表达迁移：</strong> 讲述一个物品掉进水中的小意外，准确使用 a、the、into。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A ball landed in the river beside our picnic spot. The ball floated towards a bridge. Its owner borrowed a long stick to reach it.</p><p>第一句的组织方式：A ball 首次引入对象，the river 是场景内可识别的河流，beside 短语修饰位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：on the river 通常表示在河面上，into the river 强调从外面进入水中。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-030">回看本课</a></p><h2 id="lesson-31-·-一般现在时与习惯" tabindex="-1">Lesson 31 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-31-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 31 · 一般现在时与习惯 {#lesson-31-·-一般现在时与习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Mina used to repair bicycles in her parents&#39; garage.</p><h3 id="练习-1-30" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-30" aria-label="Permalink to &quot;练习 1 {#练习-1-30}&quot;">​</a></h3><p>选 repair/repairing：Mina used to ___ bicycles.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> repair</p><p><strong>解析：</strong> used to 表过去习惯时接原形。</p></details><p><strong>表达迁移：</strong> 写一段小事业的发展，包含过去起点、现在规模和保留的习惯。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Mina used to repair bicycles in her parents&#39; garage. Now she runs a shop with three employees. She still repairs the oldest bicycles herself.</p><p>第一句的组织方式：used to 加原形 repair 表过去习惯，in 后为地点，parents&#39; 是复数所有格。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：used to repairing 把过去习惯与 be used to doing 混淆；此处应为 used to repair。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-031">回看本课</a></p><h2 id="lesson-32-·-被动语态与信息重点" tabindex="-1">Lesson 32 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-32-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 32 · 被动语态与信息重点 {#lesson-32-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The missing receipt has been found behind the counter.</p><h3 id="练习-1-31" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-31" aria-label="Permalink to &quot;练习 1 {#练习-1-31}&quot;">​</a></h3><p>补全：The receipt has ___ found.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 完成时被动为 has/have been done。</p></details><p><strong>表达迁移：</strong> 描述一次退货流程，包含找到凭证、核查和结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The missing receipt has been found behind the counter. The assistant checked the date. The customer then received a refund.</p><p>第一句的组织方式：receipt 是单数承受者，has been found 为完成时被动；behind the counter 说明发现地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：has found the receipt 是主动；receipt has found 缺少合理宾语且让收据成为发现者。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-032">回看本课</a></p><h2 id="lesson-33-·-过去完成时与先后关系" tabindex="-1">Lesson 33 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-33-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 33 · 过去完成时与先后关系 {#lesson-33-·-过去完成时与先后关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By the time we reached the shore, we had lost our map.</p><h3 id="练习-1-32" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-32" aria-label="Permalink to &quot;练习 1 {#练习-1-32}&quot;">​</a></h3><p>填 lose：We had ___ our map before we reached the shore.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lost</p><p><strong>解析：</strong> 过去完成时用过去分词 lost。</p></details><p><strong>表达迁移：</strong> 按四个时间点写脱困经历，明确哪个困难发生在更早阶段。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>By the time we reached the shore, we had lost our map. A light appeared beyond the rocks. We followed it to a small harbour.</p><p>第一句的组织方式：By the time 从句 reached 建立过去参照点，主句 had lost 回顾更早事件，our map 是宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：had lost 不表示此后才丢；它把丢地图放在到岸之前。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-033">回看本课</a></p><h2 id="lesson-34-·-间接引语与视角转换" tabindex="-1">Lesson 34 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-34-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 34 · 间接引语与视角转换 {#lesson-34-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The police told me that my bicycle had been found.</p><h3 id="练习-1-33" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-33" aria-label="Permalink to &quot;练习 1 {#练习-1-33}&quot;">​</a></h3><p>填 been/being：My bicycle had ___ found.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 过去完成时被动为 had been done。</p></details><p><strong>表达迁移：</strong> 写一条失物找回通知，说明报失时间、通知内容和当前状态。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The police told me that my bicycle had been found. I had reported it missing two years earlier. Its bell was gone, but the frame was undamaged.</p><p>第一句的组织方式：told me 引出接收信息的人；had been found 是从通知时刻回看更早找回动作的被动结构。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：police 通常作复数集合名词：The police are investigating，不用 is。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-034">回看本课</a></p><h2 id="lesson-35-·-不定式与目的" tabindex="-1">Lesson 35 · 不定式与目的 <a class="header-anchor" href="#lesson-35-·-不定式与目的" aria-label="Permalink to &quot;Lesson 35 · 不定式与目的 {#lesson-35-·-不定式与目的}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A cyclist stopped to help the shop assistant.</p><h3 id="练习-1-34" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-34" aria-label="Permalink to &quot;练习 1 {#练习-1-34}&quot;">​</a></h3><p>选 to help/helping：She stopped her journey ___ the assistant.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to help</p><p><strong>解析：</strong> 停止行程的目的是帮助，使用目的不定式。</p></details><p><strong>表达迁移：</strong> 写三句街头事件说明，分清看到的事实和每个人采取的行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A cyclist stopped to help the shop assistant. The thief dropped a bag near the door. A witness called the police instead of joining the chase.</p><p>第一句的组织方式：stopped 是主线过去动作，to help 是目的状语，the shop assistant 为 help 的宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：stop to run 是停下别的事去跑；stop running 是不再跑。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-035">回看本课</a></p><h2 id="lesson-36-·-将来进行时与过程" tabindex="-1">Lesson 36 · 将来进行时与过程 <a class="header-anchor" href="#lesson-36-·-将来进行时与过程" aria-label="Permalink to &quot;Lesson 36 · 将来进行时与过程 {#lesson-36-·-将来进行时与过程}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> At noon tomorrow, Ava will be swimming near the eastern coast.</p><h3 id="练习-1-35" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-35" aria-label="Permalink to &quot;练习 1 {#练习-1-35}&quot;">​</a></h3><p>填 swim 的形式：Ava will be ___ at noon.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> swimming</p><p><strong>解析：</strong> 进行时用 -ing，swim 双写 m。</p></details><p><strong>表达迁移：</strong> 为一次长距离活动写时间计划，包括陪同者和停止条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>At noon tomorrow, Ava will be swimming near the eastern coast. Her coach will follow in a boat. They will stop if the weather becomes dangerous.</p><p>第一句的组织方式：will be swimming 是将来进行时，At noon tomorrow 给出参照时点，near 表示附近而非已经上岸。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：will be swum 是被动形式，不表示她自己正在游；此处用 swimming。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-036">回看本课</a></p>',76)])])}const g=s(n,[["render",r]]);export{m as __pageData,g as default};
